108	\centering
109	\small
110	\begin{tabular}{lcccc}
111	\toprule
112	\textbf{Subset / Method} & $\boldsymbol{r}$ & $\boldsymbol{\eta_{\max}}$ & $\boldsymbol{K_{\mathrm{eff}}}$ & \textbf{Trans.} \\
113	\midrule
